package comparison.infrastructure.parsers

import comparison.domain.models.ReportIssueItem
import comparison.domain.ports.LyricsReportParser
import java.io.File
import services.Messages

/**
 * Parses issues report files generated by the application into structured domain models.
 */
class LyricsReportParserImpl : LyricsReportParser {

    override fun parseReport(reportFile: File): List<ReportIssueItem> {
        if (!reportFile.exists() || !reportFile.isFile) return emptyList()

        val items = mutableListOf<ReportIssueItem>()
        val lines = reportFile.readLines(Charsets.UTF_8)

        val localizedFilePrefix = Messages.get("lyric.report.file_label", "").substringBefore(":") + ":"
        val localizedPathPrefix = Messages.get("lyric.report.path_label", "").substringBefore(":") + ":"
        val localizedAudioPrefix = Messages.get("lyric.report.audio_label", "").substringBefore(":") + ":"
        val localizedIssuesPrefix = Messages.get("lyric.report.issues_label").substringBefore(":") + ":"

        var currentFileName = ""
        var currentPath = ""
        var currentAudioName = ""
        val currentIssues = mutableListOf<String>()
        var isParsingIssues = false
        var currentId = 1

        fun flushCurrentItem() {
            if (currentPath.isNotBlank()) {
                val lyricFile = File(currentPath)
                val audioFile = if (currentAudioName.isNotBlank() && lyricFile.parentFile != null) {
                    val candidate = File(lyricFile.parentFile, currentAudioName)
                    if (candidate.exists()) {
                        candidate
                    } else {
                        // Attempt matching by base name + .flac
                        val flacCandidate = File(lyricFile.parentFile, "${lyricFile.nameWithoutExtension}.flac")
                        if (flacCandidate.exists()) flacCandidate else candidate
                    }
                } else if (lyricFile.parentFile != null) {
                    val flacCandidate = File(lyricFile.parentFile, "${lyricFile.nameWithoutExtension}.flac")
                    if (flacCandidate.exists()) flacCandidate else null
                } else {
                    null
                }

                items.add(
                    ReportIssueItem(
                        id = currentId++,
                        fileName = currentFileName.ifBlank { lyricFile.name },
                        lyricFile = lyricFile,
                        audioFile = audioFile,
                        issues = currentIssues.toList()
                    )
                )
            }

            currentFileName = ""
            currentPath = ""
            currentAudioName = ""
            currentIssues.clear()
            isParsingIssues = false
        }

        for (line in lines) {
            val trimmed = line.trim()

            if (trimmed.startsWith("--------------------------------------------------")) {
                flushCurrentItem()
                continue
            }

            when {
                trimmed.startsWith("File:") || trimmed.startsWith("Arquivo:") || trimmed.startsWith(localizedFilePrefix) -> {
                    if (currentPath.isNotBlank()) {
                        flushCurrentItem()
                    }
                    currentFileName = trimmed.substringAfter(":").trim()
                    isParsingIssues = false
                }

                trimmed.startsWith("Path:") || trimmed.startsWith("Caminho:") || trimmed.startsWith(localizedPathPrefix) -> {
                    currentPath = trimmed.substringAfter(":").trim()
                    isParsingIssues = false
                }

                trimmed.startsWith("Corresponding audio:") || trimmed.startsWith("Áudio correspondente:") || trimmed.startsWith(localizedAudioPrefix) -> {
                    currentAudioName = trimmed.substringAfter(":").trim()
                    isParsingIssues = false
                }

                trimmed.startsWith("Issues:") || trimmed.startsWith("Problemas:") || trimmed.startsWith(localizedIssuesPrefix) -> {
                    isParsingIssues = true
                }

                isParsingIssues && trimmed.startsWith("-") -> {
                    currentIssues.add(trimmed.removePrefix("-").trim())
                }
            }
        }

        flushCurrentItem()
        return items
    }
}
